mapper.insert:
INSERT IGNORE INTO tbl_file_transfer_log (ft_dv_id, ft_serial_number, ft_file_kind, ft_ref_type, ft_ref_id, ft_file_name, ft_target_date, ft_status) SELECT A.ev_dv_id, A.ev_serial_number, #{kind}, 'event', A.ev_id, , COALESCE(STR_TO_DATE(LEFT(A.ev_date, 8), '%Y%m%d'), CURDATE()), 'PENDING' FROM tbl_event_data A WHERE A.ev_is_deleted = 0 AND IS NOT NULL AND TRIM() <> '' AND <> 'null'
AND A.ev_date >= #{ymd} AND A.ev_date < #{ymdNext}
AND A.ev_id = #{evId}

mapper.select:
SELECT F.ft_id, F.ft_dv_id, F.ft_file_kind, F.ft_ref_type, F.ft_ref_id, F.ft_file_name, DATE_FORMAT(F.ft_target_date, '%Y-%m-%d') AS ft_target_date, F.ft_status, F.ft_attempt_count, F.ft_device_bytes, F.ft_last_error_code, D.dv_ip FROM tbl_file_transfer_log F LEFT JOIN tbl_device D ON D.dv_id = F.ft_dv_id WHERE F.ft_status IN ('PENDING', 'FAILED') AND F.ft_target_date >= #{fromDate}
AND F.ft_target_date <= #{toDate}
AND F.ft_dv_id = #{dvId}
ORDER BY F.ft_dv_id, F.ft_target_date, F.ft_id

mapper.update:
UPDATE tbl_file_transfer_log
SET ft_status = 'PENDING'
WHERE ft_target_date = #{targetDate}
AND ft_status IN ('FAILED', 'LOST')

	AND ft_dv_id = #{dvId}
